-- Hosbah (MH-577 I1): one Stalwart Mail Server (stalwartlabs/stalwart, docker) run by the agent on
-- one of the team's servers, its HTTP management API bound to 127.0.0.1 only on admin_port.
-- admin_sealed is the generated admin secret, sealed with the team DEK bound to "mailadmin:<id>";
-- it never leaves the database except re-sealed to the target agent inside a signed operation. hostname
-- is the mail server's own name (the HELO/PTR hostname, e.g. mail.example.com) — distinct from any one
-- mail domain, since a server can host several domains.
ALTER TABLE mail_servers ADD CONSTRAINT mail_servers_status_check CHECK (status IN ('new', 'installing', 'running', 'failed', 'removing'));
ALTER TABLE mail_servers ADD CONSTRAINT mail_servers_hostname_check CHECK (hostname ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$');
ALTER TABLE mail_servers ADD CONSTRAINT mail_servers_sealed_check CHECK (admin_sealed IS NULL OR admin_sealed LIKE 'csv1:%');
ALTER TABLE mail_servers ADD CONSTRAINT mail_servers_port_check CHECK (admin_port BETWEEN 1 AND 65535);
CREATE UNIQUE INDEX mail_servers_team_server_key ON mail_servers (team_id, server_id);
CREATE UNIQUE INDEX mail_servers_id_team_key ON mail_servers (id, team_id);
CREATE UNIQUE INDEX mail_servers_team_hostname_key ON mail_servers (team_id, hostname);
